  <div class="rotation-list" id="split-list">${people.map(p=>`<div class="rotation-item split-item"><input type="checkbox" aria-label="Include ${esc(p.name)}" data-split="${esc(p.id)}" ${included.includes(p.id)?'checked':''}>${avatar(p)}<span>${esc(p.name)}</span><input class="split-value" data-split-value="${esc(p.id)}" inputmode="decimal" type="number" step="0.01" aria-label="${esc(p.name)} amount" value="${e&&startMode==='exact'&&e.shares[p.id]?(e.shares[p.id]/100).toFixed(2):''}" hidden><b class="split-preview" data-preview="${esc(p.id)}"></b></div>`).join('')}</div>
