  dialog(id?'Edit your flatmate':'A new face at home',id?'Set a break or away dates. New assignments skip unavailable people.':'Add everyone who shares the work. You can choose who joins each rotation.',`<label class="field">Name<input name="name" value="${esc(p.name)}" maxlength="60" required placeholder="e.g. Alex"></label><label class="field">Avatar colour<select name="color">${['Sage','Peach','Blue','Lilac','Mint','Yellow'].map((c,i)=>`<option value="${i}" ${p.color===i?'selected':''}>${c}</option>`).join('')}</select></label><div class="form-row"><label class="field">Away from<input type="date" name="awayFrom" value="${esc(p.awayFrom)}"></label><label class="field">Away until<input type="date" name="awayTo" value="${esc(p.awayTo)}"></label></div><label class="check-row"><input type="checkbox" name="paused" ${p.paused?'checked':''}>Take a break from all rotations</label>${id?`<button type="button" class="btn danger" data-action="deletePerson" data-id="${esc(id)}">Delete flatmate</button><p>Past activity stays in your household history.</p>`:''}`,'Save flatmate',async f=>{const from=f.get('awayFrom'),to=f.get('awayTo');if(!!from!==!!to||from&&to<from)throw new Error('Enter both away dates, with the end on or after the start.');const success=await mutate(h=>{const target=h.people.find(x=>x.id===id),values={name:f.get('name').trim(),color:Number(f.get('color')),paused:f.has('paused'),awayFrom:from,awayTo:to};if(target)Object.assign(target,values);else{if(h.people.length>=30)throw new Error('This home supports up to 30 flatmates.');h.people.push({id:uid(),...values});}record(h,'person',`${values.name} ${id?'updated their availability':'joined the home'}`);},id?'Flatmate updated':'Welcome to the home team');if(success){if(!myId&&home.people.length===1){myId=home.people[0].id;persist();render();}$('#modal').close();}});
