async function install(){if(deferredInstall){await deferredInstall.prompt();const r=await deferredInstall.userChoice;if(r.outcome==='accepted')toast('Flatflow is ready for your home screen.');deferredInstall=null;}else dialog('A happier home, in your pocket.','Flatflow works as an app on your phone.','<div class="info-box"><b>iPhone / iPad</b><br>Open this page in Safari. Tap Share, then Add to Home Screen.<br><br><b>Android</b><br>Open this page in Chrome. Tap the menu, then Install app or Add to Home screen.<br><br><b>Desktop</b><br>Use your browser’s Install button or menu when available.</div>','Got it',async()=>$('#modal').close());}
function joinLink(){dialog('Join a home','Enter the invite code or paste the invitation link your flatmate sent you.', '<label class="field">Invite code or link<input name="invite" type="text" required autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="K7M2-QX9P or https://…/#home=…"></label>', 'Join home',async f=>{const value=String(f.get('invite')).trim(),code=normalizeCode(value);let k=validKey(value)?value:new URLSearchParams(value.split('#')[1]||'').get('home');
  if(code&&!validKey(k)){backend=backend||BACKEND_URL;await connectClient();const r=await client.call({action:'redeemInvite',invite:await inviteId(code)}).catch(err=>{throw new Error(/Unsupported|Invalid household/.test(err.message)?'Invite codes aren’t switched on yet. Ask for the invitation link instead.':err.message);});k=await openKey(r.sealed,code);}
  if(!validKey(k))throw new Error('Enter an 8-character invite code or paste a complete Flatflow invitation link.');if(code)history.replaceState(null,'','#'+new URLSearchParams({home:k}));else location.hash=new URLSearchParams({home:k}).toString();await handleInvitation(!!code);});}
async function handleInvitation(confirmed=false){
 const params=new URLSearchParams(location.hash.slice(1));if(!params.has('home'))return;
 const invitedKey=params.get('home');if(!validKey(invitedKey)){toast('This invitation is invalid. Ask your flatmate for a new link.',true);return;}
 if(mode==='shared'&&key===invitedKey){if(syncState!=='Synced'){syncState='Connecting…';render();}await refresh(true);if($('#modal').open)$('#modal').close();return;}
 const join=async()=>{
 rememberCurrent();setBusy(true);try{await connectClient();const r=await client.call({action:'read',key:invitedKey,revision:-1});const joined=validateHome(r.home);home=joined;key=invitedKey;revision=r.revision;mode='shared';myId='';syncState='Synced';persist();$('#modal').close();view='settings';render();toast('You’re home. Choose your name.');}finally{setBusy(false);}};
 // Someone who typed an invite code has already said yes.
 if(confirmed)return join();
 dialog('Your flatmates saved you a place.','Join the shared household to see the same chores and updates.', `<p class="info-box">Choose your name after joining. Keep this invitation to reopen your home in another browser or installed app.${mode!=='welcome'?` ${esc(home.name)} stays in your homes list, so you can switch back any time.`:''}</p>`, 'Join this home',join);
}
